const data = $('Dataset').all();
const results = $input.all();
let correct = 0;
const wrong = [];

results.forEach((r, i) => {
  const exp = data[i].json.expected;
  const got = r.json.output.type;
  if (exp === got) correct++;
  else wrong.push({ id: data[i].json.id, expected: exp, got, confidence: r.json.output.confidence });
});

return [{ json: {
  total: results.length,
  correct,
  accuracy: (correct / results.length * 100).toFixed(1) + '%',
  wrong
}}];
